insert into public.n3vjit_question_bank(id,section,question_number,question_text,highlight_word,options,correct_answer,note,explanation) values
('f1_q1','fukushuu1',1,'かおいろが悪いですね。どうしたんですか。','かおいろが悪い (Sắc mặt kém) = かおが青い (Mặt xanh xao)','{"A":"楽しそうですね。どうしたんですか。","B":"うれしそうですね。どうしたんですか。","C":"かおが青いですね、どうしたんですか。","D":"かおが赤いですね。どうしたんですか。"}'::jsonb,'C','かおいろが悪い (Sắc mặt kém) = かおが青い (Mặt xanh xao)','Sắc mặt kém/xấu (顔色が悪い) đồng nghĩa với mặt tái xanh (顔が青い) khi mệt hoặc ốm.'),
('f1_q2','fukushuu1',2,'山田さんの おじょうさんは おいくつですか。','おじょうさん = むすめさん | おいくつ = なんさい','{"A":"山田さんの むすめさんは なんさいですか。","B":"山田さんの おねえさんは なんにんですか。","C":"山田さんの むすこさんは なんにんですか。","D":"山田さんの おにいさんは なんさいですか。"}'::jsonb,'A','おじょうさん = むすめさん | おいくつ = なんさい','お嬢さん là cách nói lịch sự chỉ con gái người khác; おいくつ = 何歳.'),
('f1_q3','fukushuu1',3,'田中先生が 来るのは たしかです。','～は たしかです = きっと～ます','{"A":"田中先生は けっして来ません。","B":"田中先生は やっと来ます。","C":"田中先生は 来ないかもしれません。","D":"田中先生は きっと来ます。"}'::jsonb,'D','～は たしかです = きっと～ます','たしかです nghĩa là chắc chắn, đồng nghĩa với きっと来ます.'),
('f1_q4','fukushuu1',4,'かれは はながいいです。','はながいい = においがよくわかる','{"A":"かれは くさが好きです。","B":"かれは すうがくがよくわかります。","C":"かれは においがよくわかります。","D":"かれは 虫が好きです。"}'::jsonb,'C','はながいい = においがよくわかる','鼻がいい: thính mũi, nhận biết mùi tốt.'),
('f1_q5','fukushuu1',5,'先生にしゅくだいを見なおしてもらいました。','見なおしてもらう = よくないところを なおしてもらう','{"A":"先生に しゅくだいを もう一度 はじめから やってもらいました。","B":"先生に しゅくだいの よくないところを なおしてもらいました。","C":"先生に しゅくだいを やめさせられました。","D":"先生に しゅくだいの よくないところを なおさせられました。"}'::jsonb,'B','見なおしてもらう = よくないところを なおしてもらう','Nhờ giáo viên xem và sửa chỗ chưa tốt, không phải làm lại từ đầu.'),
('f1_q6','fukushuu1',6,'ふたつの うち どちらかを おとり ください。','ふたつのうち どちらか = 一つ','{"A":"一つおとり ください。","B":"二つとっても いいです。","C":"どちらも おとり ください。","D":"りょうほう とってもいいです。"}'::jsonb,'A','ふたつのうち どちらか = 一つ','Chọn một trong hai cái.'),
('f1_q7','fukushuu1',7,'毎月 こづかいを 7000円も もらって います。','Số lượng + も = 多いと思う','{"A":"毎月 こづかいを 7000円の ほかに、もっと もらっています。","B":"毎月 こづかいを 7000円しか もらっていません。","C":"毎月 こづかいを 7000円 もらっているが、それは 少ないと思います。","D":"毎月 こづかいを 7000円 もらっているが、それは 多いと思います。"}'::jsonb,'D','Số lượng + も = 多いと思う','も nhấn mạnh số lượng nhiều.'),
('f1_q8','fukushuu1',8,'けっして だれにも 言わないでください。','けっして～ないでください = ～てはいけません','{"A":"ほかの人に言ってもいいです。","B":"ほかの人に言ってほしいです。","C":"ほかの人に言ってはいけません。","D":"ほかの人に言わなくてもいいです。"}'::jsonb,'C','けっして～ないでください = ～てはいけません','Tuyệt đối không được nói với ai khác.'),
('f1_q9','fukushuu1',9,'15分いないに もどります。','15分いないに = 15分 かかりません','{"A":"もどるのに ちょうど 15分 かかります。","B":"もどるのに 15分よりおおく かかります。","C":"もどるのに 15分 かかりません","D":"もどるのに 15分 ちょっと かかります。"}'::jsonb,'C','15分いないに = 15分 かかりません','Trong vòng 15 phút = chưa mất đến 15 phút.'),
('f1_q10','fukushuu1',10,'いま ごはんを 食べたばかりです。','Vた + ばかり = Vます + おわりました','{"A":"いま ごはんを 食べおわりました。","B":"いま ごはんを 食べているところです。","C":"ごはんの じゅんびが できました。","D":"これから ごはんを 食べるところです。"}'::jsonb,'A','Vた + ばかり = Vます + おわりました','Vừa mới ăn xong cơm.'),
('f1_q11','fukushuu1',11,'手紙を読んで、安心しました。','安心しました = 心配がなくなりました','{"A":"手紙を読んで、かなしくなりました。","B":"手紙を読んで、心配しました。","C":"手紙を読んで、気持ちが 悪くなりました。","D":"手紙を読んで、心配がなくなりました。"}'::jsonb,'D','安心しました = 心配がなくなりました','Yên tâm = hết lo lắng.'),
('f1_q12','fukushuu1',12,'オリンピックの 記念切手は きのう 売りきれました。','売りきれました = ぜんぶ 売れました','{"A":"オリンピックの 記念切手は きのう 売りませんでした。","B":"オリンピックの 記念切手は きのう 売りはじめました。","C":"オリンピックの 記念切手は きのう 売るつもりでした。","D":"オリンピックの 記念切手は きのう ぜんぶ 売れました。"}'::jsonb,'D','売りきれました = ぜんぶ 売れました','Bán hết sạch tem kỷ niệm.'),
('f1_q13','fukushuu1',13,'かれらに 会うのは ひさしぶりです。','ひさしぶり = ずいぶんまえ','{"A":"かれらに会うのは さびしいです。","B":"かれらに会うのは うれしいです。","C":"かれらに会うのは はじめてです。","D":"かれらに会うのは ずいぶんまえです。"}'::jsonb,'D','ひさしぶり = ずいぶんまえ','Lâu rồi mới gặp.'),
('f1_q14','fukushuu1',14,'チンさんは、今日は 欠席です。','欠席 = 休みます','{"A":"チンさんは、今日は 変わります。","B":"チンさんは、今日は 帰ります。","C":"チンさんは、今日は 休みます。","D":"チンさんは、今日は 行きます。"}'::jsonb,'C','欠席 = 休みます','Vắng mặt = nghỉ.'),
('f1_q15','fukushuu1',15,'あさっての パーティーには なるべく来てください。','なるべく = できるだけ','{"A":"あさっての パーティーには やはり 来てください。","B":"あさっての パーティーには ずっと 来てください。","C":"あさっての パーティーには できるだけ 来てください。","D":"あさっての パーティーには きっと 来てください。"}'::jsonb,'C','なるべく = できるだけ','Cố gắng hết sức có thể hãy đến.'),
('f1_q16','fukushuu1',16,'明日でも かまいません。','明日でも かまいません = 明日でも 今日でも いいです','{"A":"明日なら いいです。","B":"明日でも だめです。","C":"明日でも 今日でも いいです。","D":"今日より 明日のほうが いいです。"}'::jsonb,'C','明日でも かまいません = 明日でも 今日でも いいです','Ngày mai cũng không sao = hôm nay hay ngày mai đều được.'),
('f1_q17','fukushuu1',17,'姉の 仕事は ニュースを つたえる ことです。','ニュースを つたえる = ほうそうの仕事','{"A":"姉は ビジネスの 仕事を しています。","B":"姉は ぎんこうの 仕事を しています。","C":"姉は ほうそうの 仕事を しています。","D":"姉は けいさつの 仕事を しています。"}'::jsonb,'C','ニュースを つたえる = ほうそうの仕事','Truyền tải tin tức = công việc phát thanh/truyền hình.'),
('f1_q18','fukushuu1',18,'くつを ぬがないで はいってはいけません。','ぬがないで はいってはいけません = ぬいでから 入ってください','{"A":"くつを はく前に 入ってください。","B":"くつを ぬいでから 入ってください。","C":"くつを ぬぐ前に 入ってください。","D":"くつを はいた後で 入ってください。"}'::jsonb,'B','ぬがないで はいってはいけません = ぬいでから 入ってください','Không được để nguyên giày mà vào.'),
('f1_q19','fukushuu1',19,'そろそろ、しつれいします。','そろそろ、しつれいします = これから、帰ります','{"A":"ちょっと 入ります。","B":"どうも ありがとう ございます。","C":"どうも すみません。","D":"これから、帰ります。"}'::jsonb,'D','そろそろ、しつれいします = これから、帰ります','Xin phép về.'),
('f1_q20','fukushuu1',20,'すみません、このスプーンは よごれています。とりかえてください。','とりかえてください = ちがうのを ください','{"A":"スプーンを かえしてください。","B":"このスプーンを あらってください。","C":"フォークに かえてください。","D":"ちがうスプーンを ください。"}'::jsonb,'D','とりかえてください = ちがうのを ください','Hãy đổi cái khác / cho cái thìa khác.'),
('f1_q21','fukushuu1',21,'私は たまに 図書館を りようします。','たまに = そんなに～ません','{"A":"図書館は とても やくに たちます。","B":"私は よく 図書館へ 行きます。","C":"私は そんなに 図書館へ 行きません。","D":"図書館は あまり 便利では ありません。"}'::jsonb,'C','たまに = そんなに～ません','Thỉnh thoảng = không thường xuyên lắm.'),
('f1_q22','fukushuu1',22,'父は 青い ネクタイを して います。','ネクタイを しています = ネクタイを しめて います','{"A":"父は 青い ネクタイを かけて います。","B":"父は 青い ネクタイを はいて います。","C":"父は 青い ネクタイを きて います。","D":"父は 青い ネクタイを しめて います。"}'::jsonb,'D','ネクタイを しています = ネクタイを しめて います','Đeo cà vạt dùng する/締める, không dùng 着る.'),
('f1_q23','fukushuu1',23,'子どもは どんな ことを いやがりますか。','いやがります = きらいです','{"A":"子どもは どんな ことを したがりますか。","B":"子どもは どんな ことが きらいですか。","C":"子どもは どんな ことを やる つもりですか。","D":"子どもは どんな ことが すきですか。"}'::jsonb,'B','いやがります = きらいです','Tỏ ra ghét = không thích.'),
('f1_q24','fukushuu1',24,'これからは たばこを すわない ことに しました。','～ない ことに しました = ～ないと きめました','{"A":"これからは たばこを すっては いけません。","B":"これからは たばこを すわない ことに きまりました。","C":"これからは たばこを すわない ように して ください。","D":"これからは たばこを すわないと きめました"}'::jsonb,'D','～ない ことに しました = ～ないと きめました','Tự quyết định bỏ thuốc.'),
('f1_q25','fukushuu1',25,'私は 今 のどが かわいています。','のどが かわいています = 何か飲みたいです','{"A":"私は 今 休みたいです。","B":"私は 今 何か飲みたいです。","C":"私は 今 ねむりたいです。","D":"私は 今 何か食べたいです。"}'::jsonb,'B','のどが かわいています = 何か飲みたいです','Đang khát = muốn uống gì đó.'),
('f1_q26','fukushuu1',26,'いしかわさんは 私の 大学の せんぱいです。','せんぱい = 私が 入学する まえに おなじ 大学に 入学しました','{"A":"いしかわさんは 私と いっしょに おなじ 大学に 入学しました。","B":"いしかわさんは 私が 入学した あとで おなじ 大学に 入学しました。","C":"いしかわさんは 私と おなじ 年に ほかの 大学に 入学しました。","D":"いしかわさんは 私が 入学する まえに おなじ 大学に 入学しました。"}'::jsonb,'D','せんぱい = 私が 入学する まえに おなじ 大学に 入学しました','Tiền bối nhập học cùng trường trước tôi.'),
('f1_q27','fukushuu1',27,'私は 田中さんに「よく いらっしゃいました」といいました。','「よく いらっしゃいました」 = 私を たずねてきました','{"A":"田中さんが 私を たずねてきました。","B":"田中さんが 私を しょうかいしました。","C":"私は 田中さんを しょうかいしました。","D":"私は 田中さんを たずねてきました。"}'::jsonb,'A','「よく いらっしゃいました」 = 私を たずねてきました','Chào mừng khách đến chơi nhà.'),
('f1_q28','fukushuu1',28,'あには しごとに ねっしんな 人です。','ねっしん = いっしょうけんめい します','{"A":"あには しごとに ひつような ことを しって います。","B":"あには しごとが きらいです。","C":"あには しごとに てきとうな 人です。","D":"あには しごとを いっしょうけんめい します。"}'::jsonb,'D','ねっしん = いっしょうけんめい します','Nhiệt huyết, làm việc hết mình.'),
('f1_q29','fukushuu1',29,'こちらの いすに かけて ください。','いすに かけて ください = いすに すわって ください','{"A":"こちらの いすに すわって ください。","B":"こちらの いすに すわらないで ください。","C":"こちらの いすに にもつを おいて ください。","D":"こちらの いすに にもつを おかないで ください。"}'::jsonb,'A','いすに かけて ください = いすに すわって ください','Mời ngồi vào ghế.'),
