-- Apply 20261027_admin_roles.sql before this migration.
create table if not exists public.n3vjit_question_bank (
 id text primary key, section text not null check (section in ('fukushuu1','renshuu2','renshuu3','renshuu4','renshuu5')), question_number integer not null check (question_number > 0), question_text text not null check (length(trim(question_text)) > 0), highlight_word text not null default '', options jsonb not null check (jsonb_typeof(options) = 'object' and options ?& array['A','B','C','D'] and length(trim(options ->> 'A')) > 0 and length(trim(options ->> 'B')) > 0 and length(trim(options ->> 'C')) > 0 and length(trim(options ->> 'D')) > 0), correct_answer text not null check (correct_answer in ('A','B','C','D')), note text not null default '', explanation text not null default '', archived_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists n3vjit_question_bank_section_order on public.n3vjit_question_bank(section, question_number);
alter table public.n3vjit_question_bank enable row level security;
revoke all on public.n3vjit_question_bank from public;
grant select on public.n3vjit_question_bank to anon, authenticated;
grant insert, update on public.n3vjit_question_bank to authenticated;
drop policy if exists question_bank_read on public.n3vjit_question_bank;
create policy question_bank_read on public.n3vjit_question_bank for select to anon, authenticated using (true);
drop policy if exists question_bank_admin_insert on public.n3vjit_question_bank;
create policy question_bank_admin_insert on public.n3vjit_question_bank for insert to authenticated with check (public.n3vjit_is_admin());
drop policy if exists question_bank_admin_update on public.n3vjit_question_bank;
create policy question_bank_admin_update on public.n3vjit_question_bank for update to authenticated using (public.n3vjit_is_admin()) with check (public.n3vjit_is_admin());
on conflict (id) do nothing;
notify pgrst, 'reload schema';
